mapper.select:
SELECT ROWNUM num,a.*
from (
	select t.* from (







		UNION ALL




	/***update by leipeng 20190824**/
	) t order by mdateUnadjust desc,nvl(adjustNum,0) desc
) a

mapper.sql:
select FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, NULL AS adjusttype, FIN_PRODUCT.MDATE mdateUnadjust, FIN_PRODUCT.LIQUIDATION_DATE ldateUnadjust, NULL AS ldate, NULL AS bdate, NULL AS rdate, NULL AS mdate, NULL AS remark, FIN_PRODUCT.FINPROD_ID finprodId, NULL AS adjustNum, NULL AS status, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY, FIN_PRODUCT LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FIN_PRODUCT.FINPROD_ID = PMSI.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} and FIN_PRODUCT.P_FINPROD_ID IS NULL and FIN_PRODUCT.MDATE > = #{platDate} and FIN_PRODUCT_ADD.ISSUE_STATUS = #{ISSUE_STATUS01}
and FIN_PRODUCT.FINPROD_ID IN
#{item}
AND NVL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
and not exists (select 1 from PRD_MDATE_ADJUST where FIN_PRODUCT.FINPROD_ID = PRD_MDATE_ADJUST.FINPROD_ID)

select FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, PRD_MDATE_ADJUST.ADJUST_TYPE adjusttype, PRD_MDATE_ADJUST.MDATE_UNADJUST mdateUnadjust, PRD_MDATE_ADJUST.LDATE_UNADJUST ldateUnadjust,
PRD_MDATE_ADJUST.LDATE ldate, decode(PRD_MDATE_ADJUST.ADJUST_TYPE,#{TZLX_TQZZ},PRD_MDATE_ADJUST.MDATE,NULL) bdate, decode(PRD_MDATE_ADJUST.ADJUST_TYPE,#{TZLX_CPZQ},PRD_MDATE_ADJUST.MDATE,NULL) rdate, decode(PRD_MDATE_ADJUST.ADJUST_TYPE,#{TZLX_DQRTZ},PRD_MDATE_ADJUST.MDATE,NULL) mdate, PRD_MDATE_ADJUST.REMARK remark, FIN_PRODUCT.FINPROD_ID finprodId, PRD_MDATE_ADJUST.ADJUST_NUM adjustNum, decode(PRD_MDATE_ADJUST.ADJUST_NUM ,(select max(ADJUST_NUM) from PRD_MDATE_ADJUST pma where pma.FINPROD_ID=PRD_MDATE_ADJUST.FINPROD_ID),'E','D') status, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from PRD_MDATE_ADJUST, FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY, FIN_PRODUCT LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FIN_PRODUCT.FINPROD_ID = PMSI.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = PRD_MDATE_ADJUST.FINPROD_ID and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} and FIN_PRODUCT_ADD.ISSUE_STATUS = #{ISSUE_STATUS01}
and FIN_PRODUCT.FINPROD_ID IN
#{item}
and PRD_MDATE_ADJUST.MDATE >= to_date(#{adjustAfterMdateStart}, 'yyyy-MM-dd')
and PRD_MDATE_ADJUST.MDATE <= to_date(#{adjustAfterMdateEnd}, 'yyyy-MM-dd')
and PRD_MDATE_ADJUST.ADJUST_TYPE = #{adjustType}
AND NVL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}

mapper.select:
        select A.FINPROD_ID id, A.FINPROD_MARKET_ID || ':' || A.FINPROD_ABBR text
          from FIN_PRODUCT A
		inner join FIN_PRODUCT_ADD B
		   on A.FINPROD_ID = B.FINPROD_ID
		   and B.ISSUE_STATUS = #{ISSUE_STATUS01}
		 left join PTL_PORTFOLIO_AUTHORITY C

          on B.PORTFOLIO_ID = C.PORTFOLIO_ID
        where A.P_FINPROD_ID IS NULL

          	  and A.MDATE >= to_date(#{platDate},'yyyy-MM-dd')

          and A.FINPROD_TYPE2 = #{finprodType2}

              and (instr(A.FINPROD_MARKET_ID, #{search}) > 0 or instr(A.FINPROD_ABBR, #{search}) > 0)



          		and A.FINPROD_ID = #{initValue}


          		and C.USER_ID = #{userId}

select
nvl(T.MDATE, FIN_PRODUCT.MDATE) mdate , nvl(T.LDATE, FIN_PRODUCT.LIQUIDATION_DATE) ldateUnadjust , FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, NVL(T.adjustNum, 0) adjustNum, FIN_PRODUCT.VDATE vdate, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType from FIN_PRODUCT
/*left join PA_FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID*/ left join FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join (select FINPROD_ID, MDATE,LDATE,ADJUST_NUM adjustNum from PRD_MDATE_ADJUST where FINPROD_ID = #{finprodId} and ADJUST_NUM = ( SELECT MAX(T.ADJUST_NUM) FROM PRD_MDATE_ADJUST T WHERE T.FINPROD_ID = #{finprodId}) ) T on FIN_PRODUCT.FINPROD_ID = T.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = #{finprodId}

select count(1) from TRD_FIN_PRODUCT_DEAL_TOTAL, FIN_PRODUCT
where TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
  and TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 = #{finprodType2}
  and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
  and FIN_PRODUCT.FINPROD_ID = #{finprodId}
  and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_DATE >= to_date(#{mdate}, 'yyyy-MM-dd')
  and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_STATUS = #{tradeStatus}

select nvl(max(adjust_num),0) adjustNum
from PRD_MDATE_ADJUST
where FINPROD_ID=#{finprodId}

select FIN_PRODUCT.FINPROD_ID finprodId 
from FIN_PRODUCT,FIN_PRODUCT_ADD 
where FIN_PRODUCT.FINPROD_ID=#{finprodId}
and FIN_PRODUCT.FINPROD_TYPE2=#{finprodType2} 
and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT_ADD.ISSUE_STATUS=#{ISSUE_STATUS01}
and FIN_PRODUCT.MDATE > #{platDate}
